      source: 'Stevens（1946）測量尺度理論；Anderson, Sweeney & Williams《Statistics for Business and Economics》',
      brief: `**測量尺度決定你能做什麼統計**。這是統計學的第一道關卡，也是行銷研究問卷設計的地基——尺度選錯，後面所有分析都不成立。

**四種尺度（Stevens 1946）**：

| 尺度 | 性質 | 可做的運算 | 例子 |
|---|---|---|---|
| **名目**（nominal） | 只是分類，無順序 | 計次、眾數 | 性別、科系、品牌 |
| **順序**（ordinal） | 有順序，但**間距不等** | 加上中位數、百分位 | 教育程度、名次、滿意度排序 |
| **區間**（interval） | 間距相等，**無絕對零點** | 加上平均數、標準差 | 攝氏溫度、西元年 |
| **比率**（ratio） | 有**絕對零點** | 加上倍數比較 | 身高、所得、銷售額 |

**判斷口訣**：能不能分類 → 能不能排序 → 間距等不等 → 有沒有真正的零。

**最常考的辨別點是「絕對零點」**：攝氏 20 度**不是** 10 度的兩倍熱，因為 0°C 不代表沒有溫度；但 20 萬元確實是 10 萬元的兩倍，因為 0 元代表沒有錢。**只有比率尺度能講「幾倍」。**

**變數的另一組分法**：
- **類別變數**（質性）：名目與順序
- **數值變數**（量化）：區間與比率，再分**離散**（可數，如人數）與**連續**（可無限細分，如時間）`,
      advanced: `**李克特量表到底是順序還是區間，是這個主題最有價值的爭論**，也是面試最容易追問的一點。

嚴格說，「非常不同意～非常同意」的五個選項只保證**順序**，無法保證「同意」與「非常同意」的差距等於「普通」與「同意」的差距，因此屬順序尺度，理論上只能用中位數與無母數方法。但實務上幾乎所有行銷與管理研究都把它**當作區間尺度**處理，直接算平均數、做 t 檢定與迴歸。

理由有三，答題時能講出來就贏過多數人：
1. **多題加總**：單題是順序，但**多題構成的量表加總後**（如以 5 題測量顧客滿意度），分數的分布已接近連續，區間假設較站得住腳。這也是量表為什麼要多題的原因之一，連回 [[mkt-04-03]] 的信度概念。
2. **模擬研究顯示穩健**：多數模擬指出，當選項數達 5–7 且分布不過度偏斜時，把順序當區間對參數估計的偏誤有限。
3. **選項數越多越接近區間**：7 點或 11 點量表比 3 點量表更接近等距。

**標準答法**：「嚴格屬順序尺度，但在多題加總、選項數足夠的條件下，實務上以區間尺度處理，並在方法章節說明此一假設。」**承認假設而非假裝沒有問題，是研究訓練的核心態度。**

**尺度會被降級，不會被升級**。比率資料（實際年齡）可以歸成組別（20–29、30–39）變成順序資料，但反過來做不到——**問卷把年齡設計成勾選區間，就永久失去了算平均年齡的能力**。這是問卷設計最常見、也最無法補救的失誤，連回 [[mkt-04-01]] 的研究設計。

**尺度與統計方法的對應**（後面各章的地圖）：
- 兩個類別變數的關聯 → 卡方檢定
- 類別自變數 × 數值依變數 → t 檢定、變異數分析
- 兩個數值變數 → 相關與迴歸

**橫斷面 vs 縱貫資料**：橫斷面是同一時點的多個個體（2026 年各縣市所得），時間序列是同一個體的多個時點（台灣 2000–2026 年 GDP），追蹤資料（panel）兩者兼具。**追蹤資料的價值在於能控制「不隨時間改變的個體差異」**，因此在因果推論上遠強於橫斷面。`,
      example: `**一份問卷的尺度盤點**最能看出設計功力。假設題目依序是：（1）您的性別；（2）您的教育程度；（3）您對本服務的滿意度（1–5 分）；（4）您上個月在本服務的消費金額。

四題分別落在名目、順序、順序（實務上當區間）、比率。這代表：性別只能算比例與做卡方；教育程度可以排序、算中位數，但算「平均教育程度 = 3.4」在嚴格意義上沒有意義；消費金額則四則運算全部可用，還能講「A 群體是 B 群體的 1.8 倍」。

**若第四題被設計成「請勾選：1 千元以下／1–3 千／3–5 千／5 千以上」**，這份資料就再也算不出平均消費金額，也無法做以金額為依變數的迴歸——只能改用組中點近似，而組中點對「5 千以上」這個開放組根本無從決定。**問卷一旦發出去就無法回頭，這是尺度必須在設計階段就想清楚的原因。**`,
