      source: 'Anderson, Sweeney & Williams《Statistics for Business and Economics》；Gosset（1908）t 分配',
      brief: `**區間估計給出一個範圍加上信心水準**，同時傳達估計值與不確定性。

**通式**：\`點估計 ± 臨界值 × 標準誤\`

**母體平均數的信賴區間**：

| 情況 | 公式 | 用哪個分配 |
|---|---|---|
| σ **已知** | \`x̄ ± z × (σ/√n)\` | 標準常態 |
| σ **未知**（實務常態） | \`x̄ ± t × (s/√n)\` | **t 分配**，自由度 \`n − 1\` |

**★ 為什麼 σ 未知要改用 t 分配？**
因為改用 s 估計 σ 時**多引入了一層不確定性**（s 本身也會隨樣本變動）。t 分配比常態**尾部更厚**，臨界值更大，區間更寬——**這正是為「不知道 σ」所付出的代價**。

**t 分配的三個性質**：
1. 鐘形、對稱、中心為 0，但**比常態矮胖、尾部厚**
2. 形狀由**自由度**決定，自由度愈大愈接近常態
3. \`df ≥ 30\` 時已與常態極為接近（這是「n ≥ 30 可用 z」說法的由來）

**影響區間寬度的三個因素**：
- **信心水準↑** → 區間變寬（要更有把握就得說得更含糊）
- **樣本標準差 s↑** → 區間變寬
- **樣本數 n↑** → 區間變窄（依 \`√n\` 規律，見 [[stat-03-03]]）

**精確度與信心水準是取捨關係**——想同時「很有把握」又「很精確」，唯一的辦法是加大樣本。`,
      advanced: `**t 分配的來歷值得記**：由 Gosset 於 1908 年在都柏林的 Guinness 釀酒廠工作時提出，因公司規定不得以真名發表而署名 "Student"，故稱 **Student's t 分配**。**其動機正是小樣本問題**——釀酒的品質檢驗無法取得大量樣本，而當時的統計方法都建立在大樣本常態近似上。**這個故事說明 t 分配的存在理由就是小樣本，值得在面試中提一句。**

**t 與 z 的選擇規則**（考題常設陷阱）：
- σ **已知** → 用 z，**不論樣本大小**
- σ **未知** → 用 t，**不論樣本大小**（n 大時 t 與 z 幾乎相同，用 z 是近似而非正確）

**實務上 σ 幾乎永遠未知**，因此 t 檢定與 t 區間才是常態，z 反而是教科書為了說明才假設的情境。**若被問「什麼時候用 z、什麼時候用 t」，先答這條規則，再補一句「實務上幾乎都是 t」。**

**★ 使用 t 分配的前提是母體近似常態**，但這個要求在大樣本下可放寬——由中央極限定理，樣本平均數的抽樣分配已近似常態（見 [[stat-03-02]]）。**因此小樣本時要檢查常態性、大樣本時不必**，這與 [[stat-02-04]] 提到的「正式常態性檢定在大樣本下幾乎必然顯著」的弔詭恰好互補。

**t 分配對常態偏離的穩健性**：t 程序對「輕度偏斜」相當穩健，但對**離群值與嚴重偏斜敏感**（因為 x̄ 與 s 都受極端值影響）。小樣本且有離群值時，應改用穩健方法或無母數方法（見 [[stat-09-01]]）。

**信賴區間與樣本數規劃是同一件事的兩面**。由 \`E = t × (s/√n)\` 反解可得所需樣本數 \`n = (t × s / E)²\`，這正是 [[stat-03-03]] 的樣本數公式。**先設定想要多窄的區間，再反推要抽多少人**——這是研究設計的正規流程。

**比例的信賴區間**：\`p̂ ± z × √(p̂(1−p̂)/n)\`。注意此處用 z 而非 t，因為比例的標準誤直接由 p̂ 決定，不需另外估計一個 σ。**其適用條件是 \`np̂ ≥ 5\` 且 \`n(1−p̂) ≥ 5\`**（確保二項分配可用常態近似），**在極端比例（如不良率 0.1%）與小樣本下會失效**，此時應改用精確方法。**知道這個條件會比只會套公式高一個層次。**

**單邊信賴區間**在管理決策中常更貼切。若關心的是「平均交期最多不超過幾天」或「不良率最高不超過多少」，單邊界限比雙邊區間更直接對應決策需求，且在相同信心水準下界限更緊。**多數教科書只教雙邊，能主動提到單邊會顯得實務感較強。**`,
      example: `**信賴區間的完整計算**可用顧客等候時間說明。某門市隨機抽取 25 位顧客，測得平均等候時間 6.4 分鐘、樣本標準差 1.5 分鐘，求 95% 信賴區間。

1. σ 未知且樣本數小 → 用 t 分配，自由度 \`df = 25 − 1 = 24\`
2. 查表得 \`t(0.025, 24) ≈ 2.064\`
3. 標準誤 \`= s/√n = 1.5/√25 = 1.5/5 = 0.3\`
4. 誤差界限 \`= 2.064 × 0.3 ≈ 0.619\`
5. 區間 \`= 6.4 ± 0.619\`，即 **5.78 至 7.02 分鐘**

**若誤用 z = 1.96**，誤差界限為 0.588，區間 5.81 至 6.99——**略窄，因而高估了精確度**。小樣本時這個差距會更明顯：若 n 只有 5，\`t(0.025, 4) = 2.776\`，與 1.96 相差極大。

**區間寬度的取捨可以直接示範**。同一份資料改求 99% 信賴區間：\`t(0.005, 24) ≈ 2.797\`，誤差界限升為 0.839，區間變成 5.56 至 7.24。**信心水準由 95% 提高到 99%，代價是區間寬了約 36%。**

**這個取捨在管理上有實際意義**：若門市要對外承諾等候時間上限，選 99% 會讓承諾變得保守而失去競爭力，選 90% 則違諾風險升高。**信心水準不是統計問題，是風險偏好問題。**`,
