          explain: '檢定統計量的通式為觀察值減去假設值再除以標準誤。計算步驟如下：\n\n1. 求標準誤：\`SE = s/√n = 1.8/√36 = 1.8/6 = 0.3\`。\n2. 求檢定統計量：\`t = (x̄ − μ₀)/SE = (11.4 − 12)/0.3 = −0.6/0.3 = −2.0\`。\n\n自由度為 \`36 − 1 = 35\`，左尾臨界值約為 −1.69，因 −2.0 更為極端故拒絕虛無假設。若誤以樣本標準差 1.8 作為分母會得到約 −0.33；若僅計算分子則為 −0.6，兩者皆為漏算標準誤所致的常見錯誤。'
