          explain: '顯著水準即為型一誤差的容忍上限，將其收緊代表拒絕虛無假設所需的證據門檻提高，因而降低了無中生有的機率。然而在樣本數與資料變異固定的前提下，門檻提高同時使真實存在的效果更不容易達到拒絕標準，型二誤差機率因而上升、檢定力隨之下降。兩類錯誤在樣本數固定時呈蹺蹺板關係，欲同時降低兩者，唯一途徑是增加樣本數或降低測量誤差以縮小標準誤。'
