          pitfall: '直接答「型一比較嚴重」是最常見的答法——雖然統計慣例確實比較重視 α，但答死就失去了展現判斷力的機會。另一個地雷是定義講反了，記法是「型一無中生有、型二視而不見」。',
          schools: '**台大商研**可能追問檢定力與樣本規劃，準備四個影響因素與事前檢定力分析。**北大企研**較可能問企業情境（品管、A/B 測試），要能落到具體代價比較。'
