          answer: 0,
          explain: '前後兩次測量來自同一批員工，資料為成對結構而非獨立樣本，逕行採用一般卡方將違反觀察值獨立性的要求。成對二元資料的專用方法為 McNemar 檢定，其僅使用前後結果不一致的兩格，因為態度未發生改變者對於「是否產生變化」不提供任何資訊。此一思路與成對樣本 t 檢定僅分析前後差值完全相同。將成對資料誤當獨立樣本處理，或以適合度檢定比較前後分布，皆未能反映配對結構；而滿意與否為二元類別變數，並非可計算平均數的數值變數。'
