          answer: 0,
          explain: '無母數檢定的設計目的在於判斷分配位置是否存在差異，其計算以等級為基礎，而等級單位難以轉回具實務意義的原始尺度，因此不適合用以估計效果的實質大小；此外此類檢定亦無法如迴歸分析般同時納入多個自變數以控制干擾。若研究需要效果量估計或多變數控制，應改採保留原始尺度的穩健迴歸、以條件分位數為建模對象的分位數迴歸，或不依賴分配假設的重抽樣方法。此外無母數方法並非全無假設，觀察值獨立與測量達順序尺度等要求依然存在。'
