      source: 'Campbell & Stanley（1963）；Shadish, Cook & Campbell《Experimental and Quasi-Experimental Designs》',
      brief: `**因果推論的效力來自設計，不是統計方法**（見 [[stat-07-04]]）。這一節談設計。

**★ 兩種效度（最常混淆的一組）**：
- **內部效度**：**因果推論本身可不可信**——真的是 X 造成 Y 嗎？
- **外部效度**：**結論能不能推廣**——換一群人、換一個情境還成立嗎？

**★ 隨機分派 ≠ 隨機抽樣**（極高頻考點）：

| | 目的 | 影響 |
|---|---|---|
| **隨機抽樣** | 樣本代表母體 | **外部效度** |
| **隨機分派** | 兩組事前條件相當 | **內部效度** |

**兩者可以獨立存在**：實驗室實驗常有隨機分派（內部效度高）但受試者是大學生（外部效度低）；民調有隨機抽樣但沒有分派。

**★ 內部效度的七大威脅**（Campbell & Stanley，要能列出多數）：
1. **歷史**：研究期間發生的外部事件
2. **成熟**：受試者自然的成長或疲勞
3. **測驗**：前測本身影響後測
4. **工具**：測量工具或評分者標準改變
5. **迴歸至平均**：依極端值挑選受試者（見 [[stat-07-02]]）
6. **選擇**：兩組本來就不同
7. **流失**：中途退出者與留下者有系統性差異

**★ 對照組能一次擋掉 1、2、3、5**——因為這些因素同時作用在兩組上。`,
      advanced: `**內部效度與外部效度經常互相衝突**，這是設計取捨的核心：
- **實驗室實驗**：高度控制 → 內部效度高，但情境人工、樣本特殊 → 外部效度低
- **田野實驗**：真實情境 → 外部效度高，但干擾多、難以完全隨機 → 內部效度較低

**沒有「最好的設計」，只有「配合研究階段的設計」**：理論驗證階段優先內部效度，應用推廣階段優先外部效度。**能講出這個取捨，比背七大威脅更能顯示理解。**

**★ 流失（attrition）是最容易被忽略卻最致命的威脅**，因為它會**破壞隨機分派的效果**。若實驗組中效果不佳者中途退出，最後留下的都是有效果的人，**即使一開始是隨機分派，最終比較的兩組已不再等價**。

**防範**：報告各組的流失率與流失者的基線特徵；採**意圖治療分析**（intention-to-treat）——**不論是否完成處理，一律按最初分派的組別分析**。**這個詞能講出來會很專業。**

**準實驗設計**（無法隨機分派時的次佳方案，與 [[stat-07-04]] 的識別策略呼應）：
- **雙重差分（DID）**：有處理組與對照組、有前後期。**關鍵假設是「平行趨勢」**——若沒有處理，兩組的變化趨勢應相同。**這個假設無法直接驗證，只能用處理前的多期資料佐證**
- **斷點迴歸（RDD）**：利用門檻附近的準隨機分派（錄取分數線、補助資格門檻）。**內部效度接近實驗，但結論只適用於門檻附近的個案**——這是外部效度的代價
- **傾向分數配對（PSM）**：依可觀察特徵配對相似個案。**弱點是只能處理觀察得到的變數**（見 [[stat-07-03]]）

**★ 效度的四個層次**（Shadish 等人的完整架構，能列出即為加分）：
1. **統計結論效度**：統計推論本身是否正確（檢定力、假設違反、多重比較）
2. **內部效度**：因果關係是否成立
3. **建構效度**：操作型定義是否反映理論構念（見 [[stat-10-01]]）
4. **外部效度**：能否推廣到其他人、情境、時間

**這四層恰好把整科串起來**：[[stat-05-02]] 的檢定力對應第 1 層、[[stat-07-04]] 的因果推論對應第 2 層、[[stat-10-01]] 的測量對應第 3 層。

**霍桑效應與需求特徵**：受試者知道自己被觀察就會改變行為（霍桑效應）；猜到研究假設後配合演出（需求特徵）。**防範是盲化**——受試者不知分組（單盲）、施測者也不知（雙盲）。**管理研究難以完全盲化，因此更應注意這類威脅。**

**A/B 測試是企業最常用的隨機實驗**，其內部效度很高，但要注意：**多重比較**（見 [[stat-05-04]]）、**過早停止**（邊看邊決定何時結束會膨脹型一誤差）、以及**新奇效應**（改版初期的行為變化未必持久，短期結果不能外推到長期）。`,
      example: `**同一個研究問題的四種設計**最能展現設計優劣。假設要驗證「新版介面能提升轉換率」：

**設計 1：單組前後測**（改版後與改版前比較）
→ **最弱**。無法排除歷史（同期有促銷）、成熟（顧客本來就越用越熟）、季節因素。

**設計 2：非同等對照組**（拿另一個未改版的產品線比較）
→ 好一些，但兩組本來就不同（**選擇威脅**）。

**設計 3：雙重差分**（兩組都有前後期，比較「變化的差異」）
→ 可消除不隨時間變動的組間差異與共同的時間趨勢，**但依賴平行趨勢假設**。

**設計 4：隨機分派的 A/B 測試**
→ **內部效度最高**。隨機分派使兩組事前條件在期望上相當，同期發生的外部事件同時作用於兩組而被抵銷。

**但設計 4 仍有外部效度問題**：測試期間僅兩週，**新奇效應**可能使初期數字偏高；且測試流量若集中在特定時段或裝置，結論未必能推廣。

**流失威脅的實例**：某訓練計畫隨機分派 100 人受訓、100 人對照。訓練期間，**受訓組中 30 人因「太忙」退出**。若只比較完成訓練的 70 人與對照組 100 人，**結果會嚴重高估訓練效果**——因為退出的 30 人很可能正是最忙、也最無法從訓練獲益的一群。

**正確作法是意圖治療分析**：不論是否完成，**一律按最初分派的組別（100 vs 100）比較**。這樣得到的估計較保守，但它保住了隨機分派的效力，**才是可信的因果估計**。`,
