          schools: '**台大商研**很可能就是用這種方式測你的批判性思考，六個提問的框架可以直接套。**北大企研**與**中山**較可能包裝成企業簡報情境，記得把質疑講得有建設性而不是找碴——可以順帶提「怎麼設計才能得到可信的數字」。'
